def gaussian_matrix(
    rows: int,
    columns: int,
    numerators: tuple[tuple[int, int], ...],
    denominator: int = 1,
) -> sp.Matrix:
    if len(numerators) != rows * columns or denominator <= 0:
        raise ValueError("invalid pinned Gaussian matrix")
    return sp.Matrix(
        rows,
        columns,
        [
            sp.Rational(real, denominator)
            + I * sp.Rational(imaginary, denominator)
            for real, imaginary in numerators
        ],
    )


def sparse_gaussian_matrix(
    size: int,
    denominator: int,
    entries: tuple[tuple[int, int, int], ...],
) -> sp.Matrix:
    if denominator <= 0 or len({index for index, _, _ in entries}) != len(entries):
        raise ValueError("invalid pinned sparse Gaussian matrix")
    matrix = sp.zeros(size)
    for index, real, imaginary in entries:
        if not 0 <= index < size * size:
            raise ValueError("pinned sparse index out of range")
        matrix[index // size, index % size] = (
            sp.Rational(real, denominator)
            + I * sp.Rational(imaginary, denominator)
        )
    return matrix


@dataclass(frozen=True)
class MinorData:
    minors: tuple[sp.Expr, ...]
    inertia: tuple[int, int, int]
    signs: str
    hermitian: bool


def exact_minor_data(matrix: sp.Matrix) -> MinorData:
    hermitian = base.matrix_equal(matrix, matrix.H)
    minors = tuple(
        sp.factor(matrix[:size, :size].det(method="domain-ge"))
        for size in range(1, 5)
    )
    sign_values = tuple(int(sp.sign(value)) for value in minors)
    nonzero = all(sign in (-1, 1) for sign in sign_values)
    inertia = (
        base.inertia_from_nonzero_leading_minors(minors)
        if hermitian and nonzero
        else (-1, -1, -1)
    )
    signs = "".join(
        "+" if sign > 0 else "-" if sign < 0 else "0" for sign in sign_values
    )
    return MinorData(minors, inertia, signs, hermitian)


def add_inertias(
    parts: tuple[tuple[int, int, int], ...],
) -> tuple[int, int, int]:
    return tuple(sum(part[index] for part in parts) for index in range(3))  # type: ignore[return-value]


