def pinned_sum_one_branch() -> tuple[sp.Matrix, ...]:
    change = gaussian_matrix(8, 8, BRANCH_CHANGE_NUMERATORS)
    u = gaussian_matrix(
        4,
        4,
        BRANCH_COMMITTED_U_NUMERATORS,
        BRANCH_U_DENOMINATOR,
    )
    inverse = change.inv(method="DM")
    nilpotent = sp.zeros(8)
    nilpotent[0:4, 4:8] = u
    a1 = change * (D8 + nilpotent) * inverse
    a3 = momentum.J * a1.conjugate() * momentum.J
    a0 = sparse_gaussian_matrix(8, BRANCH_A0_DENOMINATOR, BRANCH_A0_SPARSE)
    a2 = sparse_gaussian_matrix(8, BRANCH_A2_DENOMINATOR, BRANCH_A2_SPARSE)
    return (a0, a1, a2, a3)


