def pinned_circulant(
    denominator: int,
    first_sparse: tuple[tuple[int, int, int], ...],
) -> tuple[sp.Matrix, tuple[sp.Matrix, ...]]:
    a0 = sparse_gaussian_matrix(8, 1, C_A0_SPARSE)
    a1 = sparse_gaussian_matrix(8, denominator, first_sparse)
    a2 = sparse_gaussian_matrix(8, 1, C_A2_SPARSE)
    a3 = momentum.J * a1.conjugate() * momentum.J
    blocks = (a0, a1, a2, a3)
    return momentum.assemble(blocks), blocks


def canonical(value: sp.Expr) -> sp.Expr:
    return sp.cancel(sp.expand(value))


def hermitian_inertia(matrix: sp.Matrix) -> tuple[int, int, int]:
    """Exact Hermitian congruence reduction, including singular 2-pivots."""
    if matrix.rows != matrix.cols or not base.matrix_equal(matrix, matrix.H):
        return (-1, -1, -1)
    work = sp.Matrix(matrix).applyfunc(canonical)
    positive = 0
    negative = 0
    zero = 0
    while work.rows:
        size = work.rows
        diagonal = next(
            (index for index in range(size) if canonical(work[index, index]) != 0),
            None,
        )
        if diagonal is not None:
            order = [diagonal] + [index for index in range(size) if index != diagonal]
            work = work.extract(order, order)
            pivot = canonical(work[0, 0])
            pivot_real, pivot_imaginary = sp.expand_complex(pivot).as_real_imag()
            if canonical(pivot_imaginary) != 0:
                raise ArithmeticError("Hermitian diagonal pivot is not real")
            sign = int(sp.sign(canonical(pivot_real)))
            if sign not in (-1, 1):
                raise ArithmeticError("Hermitian diagonal pivot has unknown sign")
            positive += int(sign > 0)
            negative += int(sign < 0)
            column = work[1:, 0]
            row = work[0, 1:]
            work = (work[1:, 1:] - column * row / pivot).applyfunc(canonical)
            continue

        off_diagonal = next(
            (
                (row, column)
                for row in range(size)
                for column in range(row + 1, size)
                if canonical(work[row, column]) != 0
            ),
            None,
        )
        if off_diagonal is None:
            zero += size
            break
        first, second = off_diagonal
        order = [first, second] + [
            index for index in range(size) if index not in (first, second)
        ]
        work = work.extract(order, order)
        pivot = work[:2, :2]
        if canonical(pivot.det()) == 0:
            raise ArithmeticError("Hermitian two-pivot is singular")
        positive += 1
        negative += 1
        cross = work[:2, 2:]
        work = (
            work[2:, 2:] - cross.H * pivot.inv(method="DM") * cross
        ).applyfunc(canonical)
    if positive + negative + zero != matrix.rows:
        raise ArithmeticError("inertia dimension mismatch")
    return (positive, negative, zero)


def gram_inertia(
    candidate: sp.Matrix,
    fixture,
) -> tuple[sp.Matrix, tuple[int, int, int]]:
    gram = base.dressed_gram(candidate, fixture)
    return gram, hermitian_inertia(gram)


def reality_exact(candidate: sp.Matrix, fixture) -> bool:
    return base.matrix_equal(
        fixture.reflection * candidate.conjugate() * fixture.reflection,
        candidate,
    )


def zero_sum_scope_certificate(note: str) -> bool:
    exact_statement = (
        "neither attained nor excluded" in note
        and any(
            phrase in note
            for phrase in ("sum 0", "zero-sum", "zero negative count")
        )
    )
    overclaims = (
        "we attain sum 0",
        "we attain zero-sum",
        "sum 0 exists",
        "sum zero exists",
        "zero-sum is impossible",
        "zero-sum is ruled out",
        "zero-sum is proved",
        "zero negative count is impossible",
    )
    parent_named = "block 112" in note or "block112" in note
    open_boundary = (
        "zero-sum decision" in note
        and ("remains open" in note or "remain open" in note)
    )
    return (
        exact_statement
        and parent_named
        and open_boundary
        and not any(claim in note for claim in overclaims)
    )


PARENT_DISPLAYED_PAIRED_SUMS = frozenset((1, 2, 3, 4))


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--mutation", choices=MUTATIONS, default="")
    mutation = parser.parse_args().mutation
    started = time.monotonic()
    checks = Checks()

    authority = authority_certificate(mutation)
    checks.check(
        "A-authority",
        "current authority and the Block112 parent triple plus ancestors 111--103 are content-bound",
        authority["main"] == CURRENT_MAIN
        and authority["axiom"] == authority["expected_axiom"]
        and authority["worktree_axiom"] == WORKTREE_AXIOM_BLOB
        and authority["registry"] == CURRENT_REGISTRY_BLOB
        and authority["worktree_registry"] == WORKTREE_REGISTRY_BLOB
        and authority["parent"] == PARENT_COMMIT
        and authority["parent_ancestor"]
        and all(authority[f"ancestor_{number}"] for number in range(103, 112))
        and authority["parent_note"] == authority["expected_parent"]
        and authority["parent_runner"] == PARENT_RUNNER_BLOB
        and authority["parent_cache"] == PARENT_CACHE_BLOB,
    )

    primary_fixture = base.fixture_data(PRIMARY_SHEAR)
    primary_propagators = tuple(
        momentum.momentum_block(primary_fixture.propagator, index)
        for index in range(4)
    )
    branch_blocks = pinned_sum_one_branch()
    tested_branch_blocks = list(branch_blocks)
    if mutation == "break_branch_involution":
        tested_branch_blocks[1] = tested_branch_blocks[1].copy()
        tested_branch_blocks[1][0, 0] += 1
    branch_grams = tuple(
        sp.simplify(
            momentum.E
            * branch_blocks[index]
            * primary_propagators[index]
            * momentum.F.T
        )
        for index in range(4)
    )
    branch_data = tuple(exact_minor_data(gram) for gram in branch_grams)
    branch_dressing = momentum.assemble(branch_blocks)
    branch_gram = base.dressed_gram(branch_dressing, primary_fixture)
    assembly_grams = momentum.gram_blocks(branch_blocks, primary_propagators)
    assembly_data = tuple(exact_minor_data(gram) for gram in assembly_grams)
    branch_inertia = add_inertias(tuple(item.inertia for item in assembly_data))
    paired_sum = branch_data[1].inertia[1] + branch_data[3].inertia[1]
    expected_paired_sum = 2 if mutation == "claim_floor_two" else 1
    checks.check(
        "B-sum-one-branch",
        "four exact involutions give ++++/++++/++++/----, paired sum one, and inertia (15,1,0)",
        all(
            base.matrix_equal(block * block, IDENTITY_8)
            for block in tested_branch_blocks
        )
        and base.matrix_equal(
            momentum.J * branch_blocks[0].conjugate() * momentum.J,
            branch_blocks[0],
        )
        and base.matrix_equal(
            momentum.J * branch_blocks[2].conjugate() * momentum.J,
            branch_blocks[2],
        )
        and base.matrix_equal(
            branch_blocks[3],
            momentum.J * branch_blocks[1].conjugate() * momentum.J,
        )
        and reality_exact(branch_dressing, primary_fixture)
        and all(item.hermitian for item in branch_data)
        and tuple(item.signs for item in branch_data)
        == ("++++", "++++", "++++", "----")
        and tuple(item.inertia for item in branch_data)
        == ((4, 0, 0), (4, 0, 0), (4, 0, 0), (3, 1, 0))
        and paired_sum == expected_paired_sum
        and all(item.hermitian for item in assembly_data)
        and base.matrix_equal(branch_gram, momentum.assemble_gram(assembly_grams))
        and branch_inertia == (15, 1, 0),
    )

    astar = base.global_candidate()
    primary_c, primary_c_blocks = pinned_circulant(
        PRIMARY_C_A1_DENOMINATOR,
        PRIMARY_C_A1_SPARSE,
    )
    primary_c_square = primary_c * primary_c
    primary_anticommutator = primary_c * astar + astar * primary_c
    tested_c_square = sp.Matrix(primary_c_square)
    tested_anticommutator = sp.Matrix(primary_anticommutator)
    if mutation == "break_c_square":
        tested_c_square[0, 0] += 1
    if mutation == "break_anticommutator":
        tested_anticommutator[0, 0] += 1
    primary_c_gram = base.dressed_gram(primary_c, primary_fixture)
    x_shift = sp.kronecker_product(sp.eye(8), momentum.spatial_shift())
    checks.check(
        "C-the-circulant-square-root",
        "C commutes with x-shift, C^2=I, all 1024 anticommutator entries vanish, and C is joint",
        all(base.matrix_equal(block * block, IDENTITY_8) for block in primary_c_blocks)
        and base.matrix_equal(primary_c * x_shift, x_shift * primary_c)
        and base.matrix_equal(tested_c_square, IDENTITY_32)
        and tested_anticommutator.shape == (32, 32)
        and base.matrix_equal(tested_anticommutator, ZERO_32)
        and reality_exact(primary_c, primary_fixture)
        and base.matrix_equal(primary_c_gram, primary_c_gram.H),
    )

    astar_square = astar * astar
    astar_gram = base.dressed_gram(astar, primary_fixture)
    t, s = sp.symbols("t s", real=True)
    symbolic_square = (
        t**2 * primary_c_square
        + t * s * primary_anticommutator
        + s**2 * astar_square
    )
    symbolic_target = (t**2 + s**2) * IDENTITY_32
    if mutation == "break_pythagorean_identity":
        symbolic_target = (t**2 + s**2 + 1) * IDENTITY_32
    points = (
        (sp.Rational(3, 5), sp.Rational(4, 5)),
        (sp.Rational(5, 13), sp.Rational(12, 13)),
        (sp.Rational(8, 17), sp.Rational(15, 17)),
    )
    primary_circle_inertias: list[tuple[int, int, int]] = []
    primary_circle_exact: list[bool] = []
    for coefficient_c, coefficient_star in points:
        candidate = coefficient_c * primary_c + coefficient_star * astar
        gram, inertia = gram_inertia(candidate, primary_fixture)
        primary_circle_inertias.append(inertia)
        primary_circle_exact.append(
            coefficient_c**2 + coefficient_star**2 == 1
            and base.matrix_equal(candidate * candidate, IDENTITY_32)
            and reality_exact(candidate, primary_fixture)
            and base.matrix_equal(gram, gram.H)
        )
    expected_circle_inertia = (
        (16, 0, 0) if mutation == "claim_circle_positive" else (8, 8, 0)
    )
    component_joint = (
        reality_exact(primary_c, primary_fixture)
        and reality_exact(astar, primary_fixture)
        and base.matrix_equal(primary_c_gram, primary_c_gram.H)
        and base.matrix_equal(astar_gram, astar_gram.H)
    )
    checks.check(
        "D-the-pythagorean-circle",
        "real-linearity gives (tC+sA*)^2=(t^2+s^2)I and three exact (8,8,0) circle points",
        t.is_real is True
        and s.is_real is True
        and component_joint
        and base.matrix_equal(astar_square, IDENTITY_32)
        and base.matrix_equal(symbolic_square, symbolic_target)
        and all(primary_circle_exact)
        and all(
            inertia == expected_circle_inertia
            for inertia in primary_circle_inertias
        ),
    )

    primary_c_inertia = hermitian_inertia(primary_c_gram)
    astar_inertia = hermitian_inertia(astar_gram)
    primary_c_rank = primary_c_inertia[0] + primary_c_inertia[1]
    expected_endpoint = (
        ((32, (8, 8, 0)), (8, 8, 0))
        if mutation == "claim_endpoint_regular"
        else ((12, (6, 6, 4)), (8, 8, 0))
    )
    checks.check(
        "E-endpoint-degeneracy",
        "pure C has exact rank twelve and (6,6,4), while pure A* re-verifies (8,8,0)",
        (primary_c_rank, primary_c_inertia) == expected_endpoint[0]
        and astar_inertia == expected_endpoint[1]
        and all(inertia[2] == 0 for inertia in primary_circle_inertias),
    )

    second_fixture = base.fixture_data(SECOND_SHEAR)
    second_c, second_c_blocks = pinned_circulant(
        SECOND_C_A1_DENOMINATOR,
        SECOND_C_A1_SPARSE,
    )
    second_anticommutator = second_c * astar + astar * second_c
    second_mixed = sp.Rational(3, 5) * second_c + sp.Rational(4, 5) * astar
    second_mixed_gram, second_mixed_inertia = gram_inertia(
        second_mixed,
        second_fixture,
    )
    second_c_gram, second_c_inertia = gram_inertia(second_c, second_fixture)
    second_c_rank = second_c_inertia[0] + second_c_inertia[1]
    expected_second = (
        ((7, 9, 0), 13, (6, 6, 4))
        if mutation == "mismatch_second_fixture"
        else ((8, 8, 0), 12, (6, 6, 4))
    )
    checks.check(
        "F-second-fixture",
        "at c=3/5 the exact circle point is (8,8,0) and the pure-C endpoint is rank twelve",
        all(base.matrix_equal(block * block, IDENTITY_8) for block in second_c_blocks)
        and base.matrix_equal(second_c * second_c, IDENTITY_32)
        and base.matrix_equal(second_anticommutator, ZERO_32)
        and reality_exact(second_c, second_fixture)
        and base.matrix_equal(second_c_gram, second_c_gram.H)
        and base.matrix_equal(second_mixed * second_mixed, IDENTITY_32)
        and reality_exact(second_mixed, second_fixture)
        and base.matrix_equal(second_mixed_gram, second_mixed_gram.H)
        and second_mixed_inertia == expected_second[0]
        and second_c_rank == expected_second[1]
        and second_c_inertia == expected_second[2],
    )

    note = normalized_note()
    attained_sums = set(PARENT_DISPLAYED_PAIRED_SUMS) | {paired_sum}
    expected_zero_attained = mutation == "claim_zero_sum_attained"
    checks.check(
        "G-zero-sum-scope",
        "displayed sums include one; sum zero is neither attained nor excluded by displayed computation",
        paired_sum == 1
        and 1 in attained_sums
        and ((0 in attained_sums) == expected_zero_attained)
        and zero_sum_scope_certificate(note),
    )

    scope = scope_certificate(note, mutation)
    checks.check(
        "H-scope",
        "the note preserves sum-one/circle/floor, N1--N8, W1, N5, ADM, gravity, and TOE walls",
        set(scope) == set(SCOPE_KEYS) and all(scope.values()),
    )

    print(
        "SUM_ONE_BRANCH: "
        f"signs={tuple(item.signs for item in branch_data)} "
        f"inertias={tuple(item.inertia for item in branch_data)} "
        f"paired_sum={paired_sum} full={branch_inertia}"
    )
    print(
        "MIXED_CIRCLE: "
        f"points={points} inertias={tuple(primary_circle_inertias)}"
    )
    print(
        "ENDPOINTS: "
        f"primary_C=rank{primary_c_rank}/{primary_c_inertia} "
        f"Astar={astar_inertia}; second_C=rank{second_c_rank}/{second_c_inertia}"
    )
    print(
        f"ATTAINED_PAIRED_SUMS: {sorted(attained_sums)}; "
        "sum 0 neither attained nor excluded"
    )
    print(
        f"AXIOM_AUTHORITY: origin/main={authority['main']} axiom={CURRENT_AXIOM_BLOB} "
        f"registry={CURRENT_REGISTRY_BLOB}; Block112 parent={PARENT_COMMIT}"
    )
    print(f"RUNTIME_SECONDS: {time.monotonic() - started:.3f}")
    print(
        "per_element: exact branch, square-root, anticommutator, circle, and endpoint identities are checked"
    )
    print(
        "per_site: one Grassmann mode per fine site on the antiperiodic reflection torus"
    )
    print(
        "per_mode: the paired sum-one branch and the mixed circle verify at both displayed shear fixtures"
    )
    print(
        "per_block: the interior circle points are pinned at eight-eight while the pure-circulant endpoint degenerates to rank twelve"
    )
    print(
        "lattice_wide: checked and not executed — the mixed-circle inertia mechanism, the paired zero-sum decision, curved OS positivity, the actual ADM/history transporter completion, joint gravity, the gravity constraint quotient, Records, audit retention, and TOE closure remain open"
    )
    print(
        "RESULT: the paired floor is refuted at sum one and the first exact mixed involutions form a Pythagorean circle with pinned interior inertia"
    )
    print(
        "DECISION_CUT: advance the mixed-circle mechanism and the zero-sum decision; reject floor-two and orientation readings of the paired sector"
    )
    print(
        "TOE: zero obligation retirement, retained-positive end-to-end theory count remains zero, and no TOE percentage moves"
    )
    return checks.finish()


if __name__ == "__main__":
    raise SystemExit(main())
